"events/phone-calls/the-telegram/the-telegram-phone-call.md": {
"name": "The Telegram — Phone Call",
"part-of": "The Telegram",
"location": "PGR Office",
"present": "Hania Barnaś, Zbigniew Gajda, Danuta Kowalik",
"tags": "Phone Call",
"noticed-by": "Empathy",
"when": "setup:events/phone-calls/the-telegram/the-telegram-phone-call.md",
"outcome": "At the name Barnaś, Zbigniew goes still and pale, and does not take his eyes off the receiver until the wire is read out.",
"gives": "wojewoda-disturbed-by-telegram",
"changes": "Aware of cache — true",
"setup": "The operator has a wire waiting for this number and reads it out flat, word by word, like any telegram: \"TO THE COMMITTEE STOP SERVICE PAPERS AND UNIFORM BURIED UNDER THE OLD GARDEN BED BEHIND MY HOUSE STOP TAKE THEM STOP BARNAŚ\". Zbigniew and Danuta are in the room and hear the name read aloud. She names no sending office and does not read it twice.",
"hook": "There is a telegram for the committee."
},
